INSERT INTO `proctad_email_templates` (`template_id`, `template_code`, `template_name`, `subject`, `body_html`, `body_plain`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'assignment_confirmation', 'PROCTAD Assignment Confirmation Request', 'Confirmation Required: {exam_name} - {exam_date}', '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <style>\n    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }\n    .container { max-width: 600px; margin: 0 auto; padding: 20px; }\n    .header { background: linear-gradient(135deg, #0077b6, #023e8a); color: white; padding: 30px; text-align: center; border-radius: 8px 8px 0 0; }\n    .content { background: #fff; padding: 30px; border: 1px solid #e0e0e0; }\n    .assignment-box { background: #f8f9fa; border-left: 4px solid #0077b6; padding: 15px; margin: 20px 0; }\n    .button { display: inline-block; padding: 12px 30px; background: #06d6a0; color: white; text-decoration: none; border-radius: 5px; font-weight: bold; margin: 20px 0; }\n    .footer { text-align: center; padding: 20px; font-size: 12px; color: #666; }\n    .warning { background: #fff3cd; border-left: 4px solid #ffc107; padding: 12px; margin: 15px 0; }\n  </style>\n</head>\n<body>\n  <div class=\"container\">\n    <div class=\"header\">\n      <h1>PROCTAD Assignment Confirmation</h1>\n      <p>Civil Service Commission Regional Office VIII</p>\n    </div>\n    <div class=\"content\">\n      <p>Dear <strong>{member_name}</strong>,</p>\n      \n      <p>You have been assigned as a PROCTAD member for the upcoming examination. Please review and confirm your assignment details below:</p>\n      \n      <div class=\"assignment-box\">\n        <h3 style=\"margin-top: 0;\">Assignment Details</h3>\n        <p><strong>Examination:</strong> {exam_name}</p>\n        <p><strong>Date:</strong> {exam_date}</p>\n        <p><strong>Time:</strong> {exam_time}</p>\n        <p><strong>Venue:</strong> {exam_venue}</p>\n        <p><strong>Your Role:</strong> {designation}</p>\n        <p><strong>PROCTAD ID:</strong> {proctad_id}</p>\n      </div>\n      \n      <div class=\"warning\">\n        <strong>⚠️ Action Required:</strong> Please confirm your availability by clicking the button below within 48 hours.\n      </div>\n      \n      <center>\n        <a href=\"{confirmation_url}\" class=\"button\" style=\"background:#06d6a0; margin-right:10px;\">CONFIRM ASSIGNMENT</a>&nbsp;&nbsp;<a href=\"{confirmation_url}\" class=\"button\" style=\"background:#ef476f;\">DECLINE ASSIGNMENT</a>\n      </center>\n      \n      <p style=\"font-size: 14px; color: #666; margin-top: 30px;\">\n        If you are unable to attend, use the Decline Assignment button above to notify us immediately so we can arrange a replacement.\n      </p>\n      \n      <hr style=\"border: none; border-top: 1px solid #e0e0e0; margin: 30px 0;\">\n      \n      <p style=\"font-size: 12px; color: #999;\">\n        This is an automated email. If you did not expect this assignment, please contact your Field Office immediately.\n        <br><br>\n        <strong>Note:</strong> This confirmation link will expire in 7 days.\n      </p>\n    </div>\n    <div class=\"footer\">\n      <p>Civil Service Commission Regional Office VIII<br>\n      PROCTAD Management System</p>\n    </div>\n  </div>\n</body>\n</html>', 'Dear {member_name},\r\n\r\nYou have been assigned as a PROCTAD member for the upcoming examination.\r\n\r\nASSIGNMENT DETAILS:\r\n- Examination: {exam_name}\r\n- Date: {exam_date}\r\n- Time: {exam_time}\r\n- Venue: {exam_venue}\r\n- Your Role: {designation}\r\n- PROCTAD ID: {proctad_id}\r\n\r\nACTION REQUIRED: Please confirm your availability by visiting the link below within 48 hours:\r\n\r\n{confirmation_url}\r\n\r\nIf you are unable to attend, please use the same link to decline the assignment so we can arrange a replacement.\r\n\r\nNote: This confirmation link will expire in 7 days.\r\n\r\n---\r\nCivil Service Commission Regional Office VIII\r\nPROCTAD Management System\r\n\r\nThis is an automated email. If you did not expect this assignment, please contact your Field Office immediately.', '{\"member_name\": \"Full name of PROCTAD member\", \"exam_name\": \"Name of examination\", \"exam_date\": \"Date formatted\", \"exam_time\": \"Time range\", \"exam_venue\": \"Venue name and address\", \"designation\": \"Role assigned\", \"proctad_id\": \"Member ID\", \"confirmation_url\": \"Unique confirmation link\"}', 1, '2026-02-04 08:23:50', '2026-02-04 12:52:49'),
(2, 'assignment_reminder', 'PROCTAD Assignment Confirmation Reminder', 'Reminder: Confirm Your Assignment - {exam_name}', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <style>\r\n    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }\r\n    .container { max-width: 600px; margin: 0 auto; padding: 20px; }\r\n    .header { background: linear-gradient(135deg, #ffd60a, #d9a000); color: #333; padding: 30px; text-align: center; border-radius: 8px 8px 0 0; }\r\n    .content { background: #fff; padding: 30px; border: 1px solid #e0e0e0; }\r\n    .button { display: inline-block; padding: 12px 30px; background: #ef476f; color: white; text-decoration: none; border-radius: 5px; font-weight: bold; margin: 20px 0; }\r\n    .urgent { background: #ffe5e5; border-left: 4px solid #ef476f; padding: 15px; margin: 20px 0; }\r\n  </style>\r\n</head>\r\n<body>\r\n  <div class=\"container\">\r\n    <div class=\"header\">\r\n      <h1>⏰ Confirmation Reminder</h1>\r\n    </div>\r\n    <div class=\"content\">\r\n      <p>Dear <strong>{member_name}</strong>,</p>\r\n      \r\n      <div class=\"urgent\">\r\n        <strong>URGENT:</strong> You have not yet confirmed your PROCTAD assignment for {exam_name} on {exam_date}.\r\n      </div>\r\n      \r\n      <p>We need your confirmation to finalize examination preparations. Please confirm or decline your assignment immediately.</p>\r\n      \r\n      <center>\r\n        <a href=\"{confirmation_url}\" class=\"button\">CONFIRM NOW</a>\r\n      </center>\r\n      \r\n      <p style=\"font-size: 14px; color: #666; margin-top: 20px;\">\r\n        <strong>Your assignment expires on:</strong> {expiry_date}\r\n      </p>\r\n    </div>\r\n  </div>\r\n</body>\r\n</html>', 'REMINDER: Assignment Confirmation Required\r\n\r\nDear {member_name},\r\n\r\nYou have not yet confirmed your PROCTAD assignment for {exam_name} on {exam_date}.\r\n\r\nPlease confirm or decline immediately: {confirmation_url}\r\n\r\nYour assignment expires on: {expiry_date}\r\n\r\n---\r\nCSC RO VIII - PROCTAD System', '{\"member_name\": \"Full name\", \"exam_name\": \"Examination name\", \"exam_date\": \"Date\", \"confirmation_url\": \"Confirmation link\", \"expiry_date\": \"Token expiry date\"}', 1, '2026-02-04 08:23:50', '2026-02-04 08:23:50');
